import re

def handle(input_data):
    source = input_data.get('source', '')
    findings = []

    # Pattern explanation:
    # (?:'|"(?:(?!\").)*") | (?:"(?:(?!\').)*") -> Matches '...' or "..." handling basic escapes implicitly by non-greedy/lookahead
    # More robust simple quote matching for single/double quotes containing the onex prefix
    # We look for single or double quoted strings.
    quote_pattern = re.compile(r'''(['"])(.*?)(?<!\\)\1''')

    # The topic shape: onex.<segment>.<segment>.<segment>+
    # Segment: lowercase letters, digits, hyphens? Usually slugs. Let's assume [a-z0-9-]+ or just [a-z]+.
    # Requirement: "at least three dot-separated lowercase segments after the onex prefix"
    # Pattern: onex\.[a-z0-9]+(\.[a-z0-9]+){2,}
    topic_pattern = re.compile(r'onex\.[a-z0-9]+(\.[a-z0-9]+){2,}')

    lines = source.split('\n')
    for line_num, line in enumerate(lines, 1):
        # Find all quoted strings in the line
        for match in quote_pattern.finditer(line):
            quoted_str = match.group(2)
            if topic_pattern.search(quoted_str):
                findings.append({
                    "line": line_num,
                    "content": line.strip(),
                    "topic": quoted_str
                })

    return {"findings": findings}
